import requests


class Tools:
    def __init__(self):
        self.citation = False
        self.backend_uri = "http://172.17.0.1:8000"

    async def get_latest_defect(
        self, __user__: dict = {}, __event_emitter__=None
    ) -> str:
        """
        This function makes an HTTP GET request to the backend to retrieve the most recent defect. The data includes information such as the defect type and an associated image.
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "Retrieving latest defects data from database ...",
                        "done": False,
                    },
                }
            )

        response = requests.get(f"{self.backend_uri}/latest_defect")
        if response.status_code == 200:
            results = response.json()
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": f"Getting image from: http://localhost:8000/{results['data']['image_url']} ...",
                            "done": False,
                        },
                    }
                )
                await __event_emitter__(
                    {
                        "type": "message",
                        "data": {
                            "content": f"![](http://localhost:8000/{results['data']['image_url']})"
                        },
                    }
                )
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": f"Successfully retrieved latest defect data!",
                            "done": True,
                        },
                    }
                )
                return f"STRICTLY reply in the this format only and DON'T ADD ANYTHING ELSE: 'Latest defect is {results['data']['defect_type']}"
        else:
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": "Failed to retrieve data from database. Please retry again or contact admin for more info!",
                            "done": True,
                        },
                    }
                )
            return f"Failed to retrieve data from database. Please retry again or contact admin for more info!"

    async def get_most_common_defect(
        self, __user__: dict = {}, __event_emitter__=None
    ) -> str:
        """
        This function makes an HTTP GET request to the backend to retrieve the most common defect. The data includes information such as the defect type and the number of defects in that category and the total number of defects.
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "Retrieving most common defect data from database ...",
                        "done": False,
                    },
                }
            )

        response = requests.get(f"{self.backend_uri}/most_common_defect")
        if response.status_code == 200:
            results = response.json()
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": f"Successfully retrieved most common defect data!",
                            "done": True,
                        },
                    }
                )
                return f"STRICTLY reply in the this format only and DON'T ADD ANYTHING ELSE: 'Most common defect is {results['data']['most_common_defect']} which has a count of {results['data']['most_common_defect_count']} out of {results['data']['total_defects']} total defects"
        else:
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": "Failed to retrieve data from database. Please retry again or contact admin for more info!",
                            "done": True,
                        },
                    }
                )
            return f"Failed to retrieve data from database. Please retry again or contact admin for more info!"
